-- Daily challenges for 2026-10-01: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-01

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('finding-patience-with-your-kids', 'Finding Patience with Your Kids', 'For parents and caregivers who love their children and still find themselves snapping. Each day is one small way to slow down a hard moment, so there is more room for calm, warmth and repair at home.', 'Parenting', 365, array['Parenting', 'Anger', 'Family']::text[], 1, '2026-10-01T17:00:00+00:00'::timestamptz),
  ('making-decisions-without-agonizing', 'Making Decisions Without Agonizing', 'For anyone who goes around in circles over choices big and small. Each day is one small practice in deciding with enough information, trusting your values, and moving on once the choice is made.', 'Thinking', 365, array['Decision Making', 'Worry', 'Values']::text[], 1, '2026-10-01T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('finding-patience-with-your-kids', 'making-decisions-without-agonizing');

