  ('finding-patience-with-your-kids', 303, 'Before a playdate, tell your child how long it will last and what will happen when it''s time to go.'),
  ('finding-patience-with-your-kids', 304, 'Pause and take a breath before telling siblings to stop fighting, so your words come out steady.'),
  ('finding-patience-with-your-kids', 305, 'Ask your child to help solve a recurring argument, like whose turn it is with a toy.'),
  ('finding-patience-with-your-kids', 306, 'Talk to your teen about a hard moment between you, and acknowledge your part in it.'),
  ('finding-patience-with-your-kids', 307, 'After a tense car ride, say to your child, "That ride was stressful. I''m sorry I got short with you."'),
  ('finding-patience-with-your-kids', 308, 'Put your feet up for five minutes once the kids are settled tonight.'),
  ('finding-patience-with-your-kids', 309, 'Ask a friend or family member to drop off dinner one evening when you''re stretched thin.'),
  ('finding-patience-with-your-kids', 310, 'Accept that a school project doesn''t have to look perfect, and let your child do it their way.'),
  ('finding-patience-with-your-kids', 311, 'Join your child in a favorite activity, like drawing or building blocks, for five minutes after dinner.'),
  ('finding-patience-with-your-kids', 312, 'Laugh with your kids at a funny video or picture you choose together, and share the giggle.'),
  ('finding-patience-with-your-kids', 313, 'Tell your teen one thing you admire about them, without adding any advice.'),
  ('finding-patience-with-your-kids', 314, 'Notice one moment today when your child tried their best, and tell them you saw it.'),
  ('finding-patience-with-your-kids', 315, 'Pay attention to your breathing while waiting in the car line, and let each breath slow down a little.'),
  ('finding-patience-with-your-kids', 316, 'Keep a calm phrase ready for when you''re interrupted, like "I''ll be with you in one minute."'),
  ('finding-patience-with-your-kids', 317, 'Say "Let''s start over" to your child when the morning gets off to a bad start.'),
  ('finding-patience-with-your-kids', 318, 'Tap your feet slowly on the floor while you wait for your child to finish a task, letting the rhythm settle you.'),
  ('finding-patience-with-your-kids', 319, 'Take your child''s hand and walk with them to get something done, instead of calling instructions from across the house.'),
  ('finding-patience-with-your-kids', 320, 'Help your child calm down before solving a problem, waiting until they''re ready to talk.'),
  ('finding-patience-with-your-kids', 321, 'Before a long weekend, make a loose plan with your kids for one fun thing to look forward to.'),
  ('finding-patience-with-your-kids', 322, 'Read a short story together at the end of a tough day, and focus on enjoying the time.'),
  ('finding-patience-with-your-kids', 323, 'Let your child pick a special treat for the family on a hard week, and enjoy it together.'),
  ('finding-patience-with-your-kids', 324, 'Swap a nagging reminder for a written note today, like a sticky note on the bathroom mirror that says "Teeth!"'),
