  ('finding-patience-with-your-kids', 331, 'Choose a code word with your child that means "I need a break," and honor it whenever they use it.'),
  ('finding-patience-with-your-kids', 332, 'Let a small mess sit until the end of the day, so you can enjoy time with your kids now.'),
  ('finding-patience-with-your-kids', 333, 'Ask your child what they''d like to do this weekend, and plan one of their ideas.'),
  ('finding-patience-with-your-kids', 334, 'Bring bubbles to the park and let your child chase them while you sit and watch.'),
  ('finding-patience-with-your-kids', 335, 'Let your child decide what to have for one meal this week, within reason.'),
  ('finding-patience-with-your-kids', 336, 'Give your teen a choice about a family outing, like where to eat or what to watch.'),
  ('finding-patience-with-your-kids', 337, 'Stretch for five minutes before bed, and let go of the day''s tension with each breath.'),
  ('finding-patience-with-your-kids', 338, 'Remind yourself during a tantrum that this moment will pass.'),
  ('finding-patience-with-your-kids', 339, 'Give your child a big, genuine smile when they walk into the room today.'),
  ('finding-patience-with-your-kids', 340, 'Make funny animal sounds while tidying up, and see if your child joins in.'),
  ('finding-patience-with-your-kids', 341, 'Celebrate a calm morning with a small family high five at the door.'),
  ('finding-patience-with-your-kids', 342, 'Say "I''m listening" to your teen and put down what you''re holding.'),
  ('finding-patience-with-your-kids', 343, 'Ask another parent at school pickup how they handle the after-school slump, and borrow one idea.'),
  ('finding-patience-with-your-kids', 344, 'Mention one thing that went well today to your child at bedtime, like "I liked how we cleaned up together."'),
  ('finding-patience-with-your-kids', 345, 'Watch for the first sign your toddler is getting tired at an outing, and head home before it turns into tears.'),
  ('finding-patience-with-your-kids', 346, 'Turn waiting at a restaurant into a game of tic-tac-toe on a napkin.'),
